/*
 * Every library item, archived ones too (the page hides them unless asked). Older rows
 * wrote a checklist item as a plain string: read as required, so nothing seeded before
 * DBU-03 changes meaning.
 */
(async () => {
  try {
    const rows = await Noodl.Records.query('LibraryItem', {}, { limit: 1000, plain: true });
    const checklist = (list) => (Array.isArray(list) ? list : [])
      .map((c) => (typeof c === 'string' ? { text: c, required: true } : { text: String((c && c.text) || ''), required: !(c && c.required === false) }))
      .filter((c) => c.text);
    const resources = (list) => (Array.isArray(list) ? list : [])
      .filter((r) => r && (r.url || r.file))
      .map((r) => (r.file
        ? { label: String(r.label || r.fileName || ''), file: String(r.file), fileName: String(r.fileName || '') }
        : { label: String(r.label || r.url), url: String(r.url) }));
    Outputs.items = rows
      .map((r) => ({
        id: r.objectId,
        title: r.title || '',
        brief: r.brief || '',
        handInChecklist: checklist(r.handInChecklist),
        resources: resources(r.resources),
        tags: Array.isArray(r.tags) ? r.tags.map(String) : [],
        estimatedMinutes: typeof r.estimatedMinutes === 'number' ? r.estimatedMinutes : null,
        archived: r.archived === true,
        updatedAt: r.updatedAt || null
      }))
      .sort((a, b) => a.title.localeCompare(b.title));
    Outputs.done();
  } catch (e) {
    console.error('[dbu:library]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
